SET current_snapshot_id = #{snapshotId}, updated_at = #{now}
WHERE id = #{reviewId}

mapper.select:
SELECT 
FROM growth_review review_record
INNER JOIN edu_student student ON student.id = review_record.student_id
INNER JOIN growth_review_snapshot snapshot
    ON snapshot.id = review_record.current_snapshot_id
WHERE review_record.student_id = #{studentId}
  AND review_record.period_type = #{periodType}
ORDER BY review_record.period_start DESC, review_record.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM growth_review
WHERE student_id = #{studentId}
  AND period_type = #{periodType}
  AND current_snapshot_id IS NOT NULL

